  println(i)
  i += 1
}
And here is an optimized version of the program using tail recursion:
def printNumbers(n: Int): Unit = {
  @tailrec
  def loop(i: Int): Unit = {
    if (i <= n) {
      println(i)
      loop(i + 1)
    }
  }
  loop(1)
}
