How can I retrieve data from a SQL database using C# code? Specifically, I want to retrieve all comments for a specific post, sorted by the most recent comment first. Here is the database schema:
Users table:
- user_id (primary key)
- username
- email
- password
Posts table:
- post_id (primary key)
- user_id (foreign key to Users table)
- content
- created_at
Comments table:
- comment_id (primary key)
- post_id (foreign key to Posts table)
- user_id (foreign key to Users table)
- content
- created_at
Likes table:
- like_id (primary key)
- post_id (foreign key to Posts table)
- user_id (foreign key to Users table)
- created_at
Here is the C# code to retrieve all comments for a specific post, sorted by the most recent comment first:
using System;
using System.Data.SqlClient;
namespace ExampleApp
{
    class Program
    {
        static void Main(string[] args)
        {
            string connectionString = "Server=myServerAddress;Database=myDataBase;User Id=myUsername;Password=myPassword;";
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();
                string query = "SELECT * FROM Comments WHERE post_id = @post_id ORDER BY created_at DESC";
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@post_id", post_id);
                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            int comment_id = (int)reader["comment_id"];
                            int user_id = (int)reader["user_id"];
                            string content = (string)reader["content"];
                            DateTime created_at = (DateTime)reader["created_at"];
                            Console.WriteLine("Comment ID: {0}, User ID: {1}, Content: {2}, Created At: {3}", comment_id, user_id, content, created_at);
                        }
                    }
                }
            }
        }
    }
}

