As an AI assistant, I can definitely help you with that. Here's a function in Python that can perform addition and subtraction of Roman numerals:
```python
def roman_calculator(num1, num2, operation):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    arabic_dict = {1: 'I', 4: 'IV', 5: 'V', 9: 'IX', 10: 'X', 40: 'XL', 50: 'L', 90: 'XC', 100: 'C', 400: 'CD', 500: 'D', 900: 'CM', 1000: 'M'}

    def to_arabic(roman):
        total = 0
        prev_value = None
        for char in roman:
            value = roman_dict[char]
            if prev_value is not None and prev_value < value:
                total += value - 2 * prev_value
            else:
                total += value
            prev_value = value
        return total

    def to_roman(arabic):
        result = ''
        for value, numeral in sorted(arabic_dict.items(), reverse=True):
            while arabic >= value:
                result += numeral
                arabic -= value
        return result

    arabic1 = to_arabic(num1)
    arabic2 = to_arabic(num2)

    if operation == '+':
        result = arabic1 + arabic2
    elif operation == '-':
        result = arabic1 - arabic2

    return to_roman(result)
```
