To include the distance from the user's current location to Mount Everest, you will need to first obtain the user's current location using Core Location framework. Once you have the user's current location, you can calculate the distance between the user's location and Mount Everest using the Haversine formula.
Here's an example Swift code that calculates the distance between two locations using the Haversine formula:
```
func distanceInKilometers(from: CLLocation, to: CLLocation) -> Double {
    let earthRadiusInKilometers = 6371.0
    let lat1 = from.coordinate.latitude
    let lon1 = from.coordinate.longitude
    let lat2 = to.coordinate.latitude
    let lon2 = to.coordinate.longitude
    let dLat = (lat2 - lat1).toRadians()
    let dLon = (lon2 - lon1).toRadians()
    let a = sin(dLat/2) * sin(dLat/2) + cos(lat1.toRadians()) * cos(lat2.toRadians()) * sin(dLon/2) * sin(dLon/2)
    let c = 2 * atan2(sqrt(a), sqrt(1-a))
    let distance = earthRadiusInKilometers * c
    return distance
}
extension Double {
    func toRadians() -> Double {
        return self * .pi / 180
    }
}
```
