using System;
class Star
{
    public double Luminosity;
    public double Radius;
    public double Temperature;
    public double MagneticField;
    public double RotationSpeed;
    public bool IsVariable;
    public bool IsPulsating;
    public bool IsStable;
    public Star(double luminosity, double radius, double temperature, double magneticField, double rotationSpeed, bool isVariable, bool isPulsating, bool isStable)
    {
        Luminosity = luminosity;
        Radius = radius;
        Temperature = temperature;
        MagneticField = magneticField;
        RotationSpeed = rotationSpeed;
        IsVariable = isVariable;
        IsPulsating = isPulsating;
        IsStable = isStable;
    }
    public double CalculateLifetime()
    {
        double mass = Luminosity / (4 * Math.PI * Math.Pow(Radius, 2) * Math.Pow(Temperature, 4.0));
        double lifetime = Math.Pow(mass, -2.5) * Math.Pow(Temperature, -2.5) * Math.Pow(Luminosity, 3.5);
        return lifetime;
    }
    public string PredictFate()
    {
        double mass = Luminosity / (4 * Math.PI * Math.Pow(Radius, 2) * Math.Pow(Temperature, 4.0));
        if (mass < 0.43)
        {
            return "The star will become a white dwarf.";
        }
        else if (mass >= 0.43 && mass <= 2)
        {
            return "The star will become a neutron star.";
        }
        else
        {
            return "The star will become a black hole.";
        }
    }
}
```
